"""HST Sheets ribbon UX rework (hst-ribbon-ux-calc.patch, generated by scripts/patches/generate-ribbon-ux-calc.py,
and hst-ribbon-ux-calc-commands.patch). Reads the patches and the generator's data; the generator itself needs a
patched tree (its --check runs in the fresh-tree check)."""
import importlib.util
import os
import re
import sys
import unittest
import xml.etree.ElementTree as ET

from _paths import ROOT

PATCHES = os.path.join(ROOT, "patches", "libreoffice")
sys.path.insert(0, os.path.join(ROOT, "scripts", "patches"))
import ribbon_ux_calc_data as data  # noqa: E402
import ribbon_ux_calc_menus as menus  # noqa: E402
import ribbon_ux_calc_tips as tips  # noqa: E402

spec = importlib.util.spec_from_file_location("generate_ribbon_ux_calc",
                                              os.path.join(ROOT, "scripts/patches/generate-ribbon-ux-calc.py"))
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)


def read(name):
    with open(os.path.join(PATCHES, name), encoding="utf-8") as handle:
        return handle.read()


def section(text, path):
    start = text.index(f"+++ b/{path}\n")
    end = text.find("\n--- a/", start)
    return text[start:end if end >= 0 else len(text)]


def lines(text, sign):
    return [line[1:] for line in text.splitlines() if line.startswith(sign) and not line.startswith(sign * 3)]


def po_unescape(text):
    return text.replace('\\"', '"').replace("\\n", "\n")


class CalcRibbonUxPatch(unittest.TestCase):
    patch = read("hst-ribbon-ux-calc.patch")
    ui_added = "\n".join(lines(section(patch, data.UI), "+"))
    ui_removed = "\n".join(lines(section(patch, data.UI), "-"))
    po = section(patch, data.VI_PO)

    def po_strings(self):
        found = re.findall(r'\+msgctxt "(.*)"\n\+msgid "(.*)"\n\+msgstr "(.*)"', self.po)
        return {(c, po_unescape(m)): po_unescape(s) for c, m, s in found}

    def test_files(self):
        self.assertEqual(re.findall(r"^\+\+\+ b/(\S+)", self.patch, re.M), [data.UI, data.VI_PO, data.SUPPR])

    def test_every_new_string_has_vietnamese(self):
        strings = self.po_strings()
        expected = {}
        for table in (data.LABELS, tips.DESCRIPTIONS):
            for bid, (en, vi) in table.items():
                expected[("TabbedCalc|" + bid, en)] = vi
        for name, (bid, en, vi, _image, _big, items) in menus.MENUS.items():
            expected[("TabbedCalc|" + bid, en)] = vi
            for item in items:
                if item is not None and item[2] is not None:
                    expected[(f"TabbedCalc|Menu{name}-{item[0]}", item[2])] = item[3]
        for key, vi in expected.items():
            self.assertEqual(strings.get(key), vi, key)
        self.assertEqual(len(strings), len(set(strings)))

    def test_terms(self):
        vietnamese = " ".join(self.po_strings().values())
        for wrong in ("Vĩ lệnh", "vĩ lệnh", "Phối thư", "phối thư", "Canh ", "canh ", "Basic", "Excel", "Microsoft"):
            self.assertNotIn(wrong, vietnamese)
        for label_id, (en, vi) in data.CAPTIONS.items():
            self.assertNotIn("&", en + vi)
            self.assertEqual(vi[0], vi[0].upper())
            self.assertFalse(any(w[0].isupper() for w in vi.split()[1:] if w not in ("(Pivot)", "Macro")), vi)

    def test_trailing_blocks_go(self):
        for block in data.DROP_BLOCKS:
            self.assertIn(f'id="{block}"', self.ui_removed)
            self.assertNotIn(f'id="{block}"', self.ui_added)
        self.assertNotIn('id="Extension-Menu"', self.ui_removed)

    def test_menu_buttons_have_their_menus(self):
        for name, (bid, *_rest) in menus.MENUS.items():
            self.assertIn(f'<object class="svtlo-ManagedMenuButton" id="{bid}:Menu {name}">', self.ui_added)
            self.assertIn(f'<object class="GtkMenu" id="Menu {name}">', self.ui_added)

    def test_page_and_function_commands(self):
        self.assertIn(".uno:CalcPageMargin?Page.LeftMargin:long=1800&amp;Page.RightMargin:long=1800&amp;"
                      "Page.TopMargin:long=1900&amp;Page.BottomMargin:long=1900", self.ui_added)
        self.assertIn(".uno:CalcPageSize?PaperFormat:long=4", self.ui_added)  # PAPER_A4
        self.assertIn(".uno:Orientation?isLandscape:bool=true", self.ui_added)
        self.assertIn(".uno:InsertFunction?FunctionName:string=DOCTIEN&amp;FunctionCategory:short=0", self.ui_added)
        self.assertIn(".uno:InsertFunction?FunctionName:string=VLOOKUP&amp;FunctionCategory:short=0", self.ui_added)
        for kind in ("Column", "Line", "Pie"):
            self.assertIn(f">.uno:InsertObjectChart?ChartType:string={kind}<", self.ui_added)

    def test_split_buttons(self):
        for bid in data.SPLIT_BUTTONS + ("btnFunctionsHstAutoSum", "btnViewFreezePanes"):
            self.assertIn(f'<object class="GtkMenuToolButton" id="{bid}">', self.ui_added)

    def test_convert_to_number_keeps_the_other_patch_ids(self):
        self.assertIn('<object class="sfxlo-NotebookbarToolBox" id="bxHstConvertTextToNumber">', self.ui_added)
        button = re.search(r'<object class="GtkToolButton" id="btnHstConvertTextToNumber">(.*?)</object>',
                           self.ui_added, re.S).group(1)
        self.assertIn(">.uno:HstConvertTextToNumber<", button)
        self.assertIn(">cmd/sc_numberformatstandard.png<", button)

    def test_removed_commands_stay_in_the_menu_bar(self):
        """Commands whose last ribbon button goes are listed in the release notes; spot-check the big ones."""
        for command in (".uno:Shuffle", ".uno:Hyphenate", ".uno:AuditingFillMode", ".uno:RecalcPivotTable"):
            self.assertIn(command, self.ui_removed)
        # refresh and delete pivot table stay on the Pivot Table contextual tab (not touched by this patch)
        self.assertNotIn('id="btnHstCtxPivotRefresh"', self.ui_removed)
        self.assertNotIn('id="btnHstCtxPivotDelete"', self.ui_removed)


class CalcRibbonUxSuppr(unittest.TestCase):
    def test_only_changed_items(self):
        old = ET.fromstring('<interface><object class="GtkToolButton" id="a"/><object class="GtkMenuItem" id="m"/>'
                            '<object class="GtkToolButton" id="b"/></interface>')
        new = ET.fromstring('<interface><object class="GtkToolButton" id="a"/><object class="GtkToolButton" id="c"/>'
                            '</interface>')
        line = f"{data.UI}://%s[@id='%s'] button-no-label\n"
        text = "x.ui://GtkLabel[@id='z'] orphan-label\n" + line % ("GtkToolButton", "a") + line % ("GtkMenuItem", "m") \
            + line % ("GtkToolButton", "b") + line % ("GtkToolButton", "stale") + "y.ui://x\n"
        out = gen.suppr_update(text, old, new)
        self.assertEqual(out, "x.ui://GtkLabel[@id='z'] orphan-label\n" + line % ("GtkToolButton", "a")
                         + line % ("GtkToolButton", "stale") + line % ("GtkToolButton", "c") + "y.ui://x\n")


class CalcRibbonUxCommands(unittest.TestCase):
    patch = read("hst-ribbon-ux-calc-commands.patch")

    def test_slot_is_declared_everywhere(self):
        name = data.FIT_WIDTH_COMMAND.removeprefix(".uno:")
        self.assertIn("+#define SID_HST_FIT_TO_PAGES_WIDE (SC_RESOURCE_START+23)", self.patch)
        self.assertIn(f"+SfxVoidItem {name} SID_HST_FIT_TO_PAGES_WIDE", section(self.patch, "sc/sdi/scalc.sdi"))
        self.assertIn("+    SID_HST_FIT_TO_PAGES_WIDE [ ExecMethod = Execute; StateMethod = GetState; ]",
                      section(self.patch, "sc/sdi/docsh.sdi"))
        cxx = section(self.patch, "sc/source/ui/docshell/docsh4.cxx")
        self.assertEqual(cxx.count("+        case SID_HST_FIT_TO_PAGES_WIDE:"), 1)
        self.assertIn("+            case SID_HST_FIT_TO_PAGES_WIDE:", cxx)
        self.assertIn("ScPageScaleToItem(1, 0)", cxx)
        self.assertIn(f'+      <node oor:name="{data.FIT_WIDTH_COMMAND}" oor:op="replace">', self.patch)

    def test_unfreeze_split_buttons_and_chart_type(self):
        self.assertIn("+SfxVoidItem HstUnfreezePanes SID_HST_UNFREEZE_PANES", self.patch)
        self.assertIn("+        case SID_HST_UNFREEZE_PANES:", section(self.patch, "sc/source/ui/view/tabvwsh3.cxx"))
        self.assertIn("rSet.DisableItem(nWhich)", section(self.patch, "sc/source/ui/view/tabvwsha.cxx"))
        self.assertIn('+  <menu:menuitem menu:id=".uno:HstUnfreezePanes"/>', self.patch)
        for popup, command in (("hstautosum", ".uno:AutoSum"), ("hstmergecells", ".uno:ToggleMergeCells")):
            self.assertIn(f"+          <value>private:resource/popupmenu/{popup}</value>", self.patch)
            self.assertIn(f"+          <value>{command}</value>", self.patch)
            self.assertIn(f"+\tsc/uiconfig/scalc/popupmenu/{popup} \\", self.patch)
        self.assertIn("SfxStringItem ChartType FN_PARAM_6)", section(self.patch, "svx/sdi/svx.sdi"))
        self.assertIn("lcl_HstSetChartType(xChartDoc, aHstChartType);", self.patch)
        po = section(self.patch, "translations/source/vi/officecfg/registry/data/org/openoffice/Office/UI.po")
        self.assertIn('+  <menu:menuitem menu:id=".uno:AutoSum?Function:string=sum"/>', self.patch)
        for vi in ("Tổng", "Co vừa một trang ngang", "Bỏ cố định ngăn", "Trung bình", "Biểu đồ cột", "Biểu đồ tròn"):
            self.assertIn(f'+msgstr "{vi}"', po)


if __name__ == "__main__":
    unittest.main()
